const items = $input.all();
const aiResponse = items[0].json.message.content;
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch(e) {
  parsed = { seo_title: 'Error', meta_description: aiResponse, seo_score: 0 };
}
return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    pageUrl: items[0].json.body?.url || '',
    seoTitle: parsed.seo_title || '',
    metaDescription: parsed.meta_description || '',
    primaryKeywords: Array.isArray(parsed.primary_keywords) ? parsed.primary_keywords.join(', ') : '',
    secondaryKeywords: Array.isArray(parsed.secondary_keywords) ? parsed.secondary_keywords.join(', ') : '',
    ogTitle: parsed.og_title || '',
    ogDescription: parsed.og_description || '',
    ogType: parsed.og_type || 'article',
    twitterTitle: parsed.twitter_title || '',
    twitterDescription: parsed.twitter_description || '',
    twitterCard: parsed.twitter_card || 'summary_large_image',
    h1Suggestion: parsed.h1_suggestion || '',
    seoScore: parsed.seo_score || 0,
    readabilityScore: parsed.readability_score || '',
    internalLinks: Array.isArray(parsed.internal_link_suggestions) ? parsed.internal_link_suggestions.join(', ') : '',
    altTexts: Array.isArray(parsed.alt_text_suggestions) ? parsed.alt_text_suggestions.join(', ') : ''
  }
}];
